<script setup lang="ts">
import { ref } from 'vue';import type { useStudentEditor } from '../composables/useStudentEditor';import MessagePanel from '../components/MessagePanel.vue';import StudentForm from '../components/StudentForm.vue';import DuplicateDialog from '../components/DuplicateDialog.vue';import DeleteDialog from '../components/DeleteDialog.vue';const props=defineProps<{state:ReturnType<typeof useStudentEditor>} >();const emit=defineEmits<{back:[];saved:[]}>();const deleting=ref(false);async function save(reason?:string){if(await props.state.save(reason))emit('saved');}async function remove(reason:string){if(await props.state.remove(reason)){deleting.value=false;emit('saved');}}function reset(){if(!props.state.dirty.value||window.confirm('編集内容を読込時の値へ戻しますか。'))props.state.reset();}async function reload(){const d=props.state.data.value;if(d&&window.confirm('編集内容を破棄して最新情報を読み込みますか。'))await props.state.load(d.studentId,d.form.returnContextId||'');}
</script>
<template><h1>学生登録 {{state.data.value?.studentId ? state.data.value.permissions.update?'／編集':'／参照':'／新規'}}</h1><MessagePanel :message="state.message.value" :error="state.error.value"/><template v-if="state.data.value"><p>学生管理番号 {{state.data.value.studentId||'新規'}}　更新日時 {{state.data.value.updatedAt||'－'}}　更新者 {{state.data.value.updatedBy||'－'}}</p><form @submit.prevent="save()"><StudentForm :data="state.data.value" :busy="state.busy.value" @update:form="state.data.value.form=$event" @options="state.options"/><div class="actions"><button v-if="state.data.value.permissions.update" type="submit" class="primary" :disabled="state.busy.value">{{state.data.value.studentId?'更新':'登録'}}</button><button type="button" :disabled="state.busy.value" @click="reset">{{state.data.value.studentId?'編集取消':'入力クリア'}}</button><button v-if="state.data.value.studentId" type="button" :disabled="state.busy.value" @click="reload">最新情報を再読込</button><button type="button" :disabled="state.busy.value" @click="$emit('back')">検索へ戻る</button><button v-if="state.data.value.studentId && state.data.value.permissions.delete" type="button" class="danger" :disabled="state.busy.value" @click="deleting=true">論理削除</button></div></form><DuplicateDialog v-if="state.duplicate.value" :candidates="state.duplicate.value.candidates||[]" :count="state.duplicate.value.candidateCount||0" :busy="state.busy.value" @confirm="save" @cancel="state.cancelDuplicate"/><DeleteDialog v-if="deleting" :busy="state.busy.value" @confirm="remove" @cancel="deleting=false"/></template></template>
